package layout //nolint:testpackage // tests the layout tree and its unexported helpers

// Taffy's fixtures (testdata/taffy, see LICENSE-taffy): trees with their boxes as Chrome
// laid them out, generated by Taffy's gentest and kept left-to-right only.

import (
	"encoding/xml"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"unicode/utf8"
)

type taffyFixture struct {
	Name     string
	Rounding bool
	Viewport [2]string
	Root     *fixtureNode
}

type fixtureNode struct {
	Style    map[string]string
	IsText   bool
	Text     string
	Children []*fixtureNode
	Want     fixtureBox
}

type fixtureBox struct {
	X, Y, Width, Height float32
	Rows, Columns       *string
}

func (n *fixtureNode) walk(fn func(*fixtureNode)) {
	fn(n)
	for _, c := range n.Children {
		c.walk(fn)
	}
}

type xmlFixtures struct {
	Tests []xmlTest `xml:"test"`
}

type xmlTest struct {
	Name     string `xml:"name,attr"`
	Rounding string `xml:"use-rounding,attr"`
	Viewport struct {
		Width  string `xml:"width,attr"`
		Height string `xml:"height,attr"`
	} `xml:"viewport"`
	Input struct {
		Nodes []xmlNode `xml:",any"`
	} `xml:"input"`
	Expectations struct {
		Nodes []xmlNode `xml:",any"`
	} `xml:"expectations"`
}

type xmlNode struct {
	XMLName  xml.Name
	Attrs    []xml.Attr `xml:",any,attr"`
	Text     string     `xml:",chardata"`
	Children []xmlNode  `xml:",any"`
}

func loadTaffySuite(suite string) ([]taffyFixture, error) {
	data, err := os.ReadFile(filepath.Join("testdata", "taffy", suite+".xml"))
	if err != nil {
		return nil, err
	}
	var doc xmlFixtures
	if err = xml.Unmarshal(data, &doc); err != nil { //nolint:musttag // xmlNode.XMLName records names
		return nil, err
	}
	fixtures := make([]taffyFixture, 0, len(doc.Tests))
	for _, t := range doc.Tests {
		if len(t.Input.Nodes) != 1 || len(t.Expectations.Nodes) != 1 {
			return nil, fmt.Errorf("%s: want one root in input and expectations", t.Name)
		}
		root, ferr := fixtureTree(t.Input.Nodes[0], t.Expectations.Nodes[0])
		if ferr != nil {
			return nil, fmt.Errorf("%s: %w", t.Name, ferr)
		}
		fixtures = append(fixtures, taffyFixture{
			Name:     t.Name,
			Rounding: t.Rounding != "false",
			Viewport: [2]string{orMaxContent(t.Viewport.Width), orMaxContent(t.Viewport.Height)},
			Root:     root,
		})
	}
	return fixtures, nil
}

func fixtureTree(in, want xmlNode) (*fixtureNode, error) {
	if want.XMLName.Local != "node" {
		return nil, fmt.Errorf("expectation <%s>, want <node>", want.XMLName.Local)
	}
	if len(in.Children) != len(want.Children) {
		return nil, fmt.Errorf("<%s> has %d children, its expectation %d",
			in.XMLName.Local, len(in.Children), len(want.Children))
	}
	n := &fixtureNode{Style: map[string]string{}, IsText: in.XMLName.Local == "text"}
	for _, a := range in.Attrs {
		n.Style[a.Name.Local] = a.Value
	}
	if len(in.Children) == 0 {
		n.Text = strings.TrimSpace(in.Text)
	}
	box, err := expectedBox(want.Attrs)
	if err != nil {
		return nil, err
	}
	n.Want = box
	for i := range in.Children {
		c, cerr := fixtureTree(in.Children[i], want.Children[i])
		if cerr != nil {
			return nil, cerr
		}
		n.Children = append(n.Children, c)
	}
	return n, nil
}

func expectedBox(attrs []xml.Attr) (fixtureBox, error) {
	var b fixtureBox
	for _, a := range attrs {
		var dst *float32
		switch a.Name.Local {
		case "x":
			dst = &b.X
		case "y":
			dst = &b.Y
		case "width":
			dst = &b.Width
		case "height":
			dst = &b.Height
		case "resolved-rows":
			b.Rows = &a.Value
			continue
		case "resolved-columns":
			b.Columns = &a.Value
			continue
		default:
			continue
		}
		v, err := strconv.ParseFloat(a.Value, 32)
		if err != nil {
			return b, fmt.Errorf("%s=%q: %w", a.Name.Local, a.Value, err)
		}
		*dst = float32(v)
	}
	return b, nil
}

func orMaxContent(v string) string {
	if v == "" {
		return "max-content"
	}
	return v
}

// Ahem text, as Taffy's tests measure it: every glyph a 10×10 square, lines broken only at
// zero-width spaces.
const (
	ahemBreak = "\u200b"
	ahemGlyph = 10
)

func ahemContentWidths(text string) (float32, float32) {
	if text == "" {
		return 0, 0
	}
	longest, total := 0, 0
	for _, word := range strings.Split(text, ahemBreak) {
		n := utf8.RuneCountInString(word)
		longest = maxInt(longest, n)
		total += n
	}
	return float32(longest * ahemGlyph), float32(total * ahemGlyph)
}

func ahemHeight(text string, width float32) float32 {
	perLine := int(math.Floor(float64(width / ahemGlyph)))
	lines, current := 1, 0
	for _, word := range strings.Split(text, ahemBreak) {
		n := utf8.RuneCountInString(word)
		if current+n > perLine {
			if current > 0 {
				lines++
			}
			current = n
		} else {
			current += n
		}
	}
	return float32(lines * ahemGlyph)
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}
